function forecast(r){const o=scopeOf(r);if(!o.total||!o.open)return "";const open=(BYREL[r.id]||[]).filter(s=>s.st!=="Done");const pts=sum(open,s=>s.pts);const tms=(r.team||[]).map(tmOf).filter(Boolean);const per=sum(tms,t=>capOf(t,"x")*.85);if(!per)return "";const its=Math.ceil(pts/per),land=addD(CURSP&&spOf(CURSP).to,14*its);return land>r.date?`Forecast: ${pts} points remain against about ${Math.round(per)} points per iteration, so scope lands around ${fd(land)}, ${dif(land,r.date)} days after the target.`:`Forecast: ${pts} points remain and fit before the target.`}

