function finOf(f,tid){const key=f.id+"@"+tid;R.pl=R.pl||{};if(R.pl[key])return R.pl[key];const ss=(BYFT[f.id]||[]).filter(s=>s.tm===tid&&s.st!=="Done"),t=tmOf(tid);let it=(ss.filter(s=>s.sp).map(s=>s.sp).sort().pop())||"26.4.1";const back=sum(ss.filter(s=>!s.sp),s=>s.pts);if(back){const n=Math.ceil(back/Math.max(1,capOf(t,"x")*2.2));const i=["26.4.1","26.4.2","26.4.3","26.4.4","26.4.5"].indexOf(it);it=["26.4.1","26.4.2","26.4.3","26.4.4","26.4.5"][Math.min(4,i+n)]}return R.pl[key]=it}
function cellLoad(tid,it){const t=tmOf(tid),cap=capOf(t,it==="26.4.1"?CURSP:"x");const idx=["26.4.1","26.4.2","26.4.3","26.4.4","26.4.5"].indexOf(it);let load;if(idx<3)load=sum(STORY.filter(s=>s.tm===tid&&s.sp===it),s=>s.pts);else{const f=FEAT.filter(x=>x.pi==="26.4"&&x.tms.includes(tid)),back=sum(STORY.filter(s=>s.tm===tid&&s.st!=="Done"&&!s.sp&&f.some(x=>x.id===s.ft)),s=>s.pts);load=idx===3?Math.min(back,Math.round(cap*.88)):Math.min(Math.max(0,back-Math.round(cap*.88)),Math.round(cap*.45))}return {load,cap:it==="26.4.5"?Math.round(cap*.5):cap}}
