/* work providers and the delivery performance tab */
const FR={"To do":1,"In progress":.6,"In review":.3,"Testing":.2};
WORK.push({kind:"Stories and defects",tag:"STORY",fn:n=>STORY.filter(s=>s.as===n&&s.sp===CURSP&&s.st!=="Done").map(s=>({id:s.id,t:s.t,sub:tmName(s.tm)+" · "+s.st+" · "+s.pts+" pts",due:fd(CUR.to),st:s.blk?"bad":SC[s.st],hrs:Math.round(s.pts*3.75*(FR[s.st]||1)*10)/10,go:()=>{go("agile_board");setTimeout(()=>storyDrawer(s.id),60)}}))});
WORK.push({kind:"Pull requests",tag:"PR",fn:n=>PRS.filter(p=>p.st!=="Merged"&&(p.au===n||p.rv.includes(n))).map(p=>({id:p.id,t:p.t,sub:(p.au===n?"Author":"Reviewer")+" · "+p.st+" · "+p.age+" days",due:"",st:p.ck==="failing"?"bad":p.st==="Changes requested"?"warn":"info",hrs:p.au===n?.5:1,go:()=>{go("agile_board");setTimeout(()=>prDrawer(p.id),60)}}))});
WORK.push({kind:"Release readiness tasks",tag:"REL",fn:n=>ALLR().filter(isOpen).flatMap(r=>tasksOf(r).filter(t=>t.own===n&&!["Done","Waived"].includes(tst(r,t))).map(t=>({id:t.id,t:t.t,sub:r.id+" "+r.n+" · "+t.gate,due:fd(t.due),st:dueCls(t,tst(r,t))?"bad":TSC[tst(r,t)],hrs:t.auto?.5:t.gate==="Hard"?2:1,go:()=>{S.v.rel_v=2;R.sel=r.id;go("itsm_rel")}})))});
const _pf={};
function perfOf(n){if(_pf[n]&&_pf[n].k===STORY.length)return _pf[n].v;const rec=who(n)||{};const sp=PASTSP.slice(2);const mine=STORY.filter(s=>s.as===n&&s.st==="Done"&&sp.includes(s.sp));const tms=TEAM.filter(t=>t.mem.some(m=>m.n===n));const sprints=Math.max(1,sp.length);const rv=PRS.filter(p=>p.st==="Merged"&&p.rv.includes(n)),au=PRS.filter(p=>p.st==="Merged"&&p.au===n);const defs=mine.filter(s=>s.ty==="Defect").length;
 const v={n:mine.length,vel:rnd1(sum(mine,s=>s.pts)/sprints),cy:rnd1(med(mine.map(s=>s.cy))),rv:rnd1(med(rv.map(p=>p.rvh))),rvn:rv.length,prs:au.length,esc:STORY.filter(s=>s.esc&&s.as===n).length,def:mine.length?Math.round(defs/mine.length*100):0,tms,kind:rec.kind};_pf[n]={k:STORY.length,v};return v}
function perfBase(n){const me=perfOf(n),tmn=new Set(me.tms.flatMap(t=>t.mem.map(m=>m.n)));tmn.delete(n);const peers=DIR.filter(d=>d.name!==n&&d.kind===me.kind&&perfOf(d.name).n>0).map(d=>perfOf(d.name));const team=[...tmn].map(perfOf).filter(x=>x.n>0);const m=(a,k)=>a.length?rnd1(med(a.map(x=>x[k]))):null;return {team:{vel:m(team,"vel"),cy:m(team,"cy"),rv:m(team.filter(x=>x.rvn>0),"rv"),esc:m(team,"esc"),def:m(team,"def"),k:team.length},peer:{vel:m(peers,"vel"),cy:m(peers,"cy"),rv:m(peers.filter(x=>x.rvn>0),"rv"),esc:m(peers,"esc"),def:m(peers,"def"),k:peers.length}}}
P360_TABS.push({label:"Delivery performance",fn:rec=>{const p=perfOf(rec.name);if(!p.n&&!p.rvn)return `<div class="row"><span class="pill mute" data-role="metric">Stories 0</span><span class="pill mute" data-role="metric">Pull requests 0</span><span class="pill mute" data-role="metric">Reviews 0</span><span class="muted small">last 4 sprints, no baseline</span></div>`;const b=perfBase(rec.name),w=workload(rec.name);
 const row=(l,v,u,tb,pb,hi,std,f)=>{const ref=tb!=null?tb:pb;const ok=ref==null?"mute":(hi?v>=ref*.95:v<=ref*1.05)?"good":(hi?v>=ref*.8:v<=ref*1.25)?"warn":"bad";return `<tr><th scope="row">${l}<br><small class="muted">${f}</small></th><td class="num"><b>${v}${u}</b></td><td class="num">${tb!=null?tb+u:"n/a"}</td><td class="num">${pb!=null?pb+u:"n/a"}</td><td>${std}</td><td><span class="pill ${ok}">${ref==null?"No baseline":ok==="good"?"At or better":ok==="warn"?"Slightly off":"Below baseline"}</span></td></tr>`};
 const st=p.vel>=(b.team.vel||0)*.95&&(b.team.cy==null||p.cy<=b.team.cy*1.1);
 return `<p class="story" data-role="story">${esc(rec.name)} delivered <b>${p.n} items</b> in the last four sprints at <b>${p.vel} points a sprint</b> with a median cycle time of <b>${p.cy} days</b>. Against ${esc(p.tms.map(t=>t.n).join(" and ")||"the team")} that is ${st?"at or above the team baseline":"below the team baseline"}${b.peer.vel!=null?"; against "+b.peer.k+" peers of the same type (".concat(KINDS[rec.kind]||"person",") it is ",p.vel>=b.peer.vel?"above":"below the median of "+b.peer.vel):""}. Current load is ${w.pct}%${w.pct<75?", so there is room for more work":w.pct>95?", so adding work will hurt delivery":""}.</p>
 <div class="tscroll"><table><thead><tr><th>Measure</th><th>${esc(rec.name.split(" ")[0])}</th><th>Team median</th><th>Peer median</th><th>Standard</th><th>Verdict</th></tr></thead><tbody>${row("Velocity",p.vel," pts",b.team.vel,b.peer.vel,1,"Team average per member","Points done ÷ sprints (last 4)")}${row("Cycle time",p.cy," d",b.team.cy,b.peer.cy,0,"5 days or less","Median days from start to done")}${row("PR review time",p.rvn?p.rv:0," h",b.team.rv,b.peer.rv,0,"4 hours","Median hours to first review of merged work")}${row("Defects escaped",p.esc,"",b.team.esc,b.peer.esc,0,"Zero","Production defects traced to their work")}${row("Defect share of work",p.def,"%",b.team.def,b.peer.def,0,"Under 25%","Defect fixes ÷ items done")}</tbody></table></div>
 <p class="muted small">Peers are other ${esc((KINDS[rec.kind]||"people").toLowerCase())}s with delivery data. Measures describe the work and the team's system, not the person; use them to ask questions, not to rank people. ${fchip("m_rel_esc","Defect escape rate")}</p>`}});

