SEARCHX.push(()=>{const o=[];ALLR().filter(r=>isOpen(r)||r.act>="2026-09-01").forEach(r=>o.push({g:"Releases",t:r.id+" "+r.n,m:r.st+" · "+fd(r.date),c:"--u3",f:()=>{go("itsm_rel");relDrawer(r.id)},k:r.svc+" "+r.ver+" release "+r.ty}));FEAT.forEach(f=>o.push({g:"Features",t:f.id+" "+f.t,m:f.st+" · PI "+f.pi,c:"--p4",f:()=>{go("agile_art");featDrawer(f.id)},k:f.svc+" wsjf "+f.kind}));EPICS.forEach(e=>o.push({g:"Epics",t:e.id+" "+e.n,m:e.kind,c:"--p4",f:()=>{go("agile_art");epicDrawer(e.id)},k:e.obj}));TEAM.forEach(t=>o.push({g:"Teams",t:t.n,m:artN(t.art),c:"--s3",f:()=>{R.bt=t.id;R.kt=t.id;S.v.rel_bv=6;R.teamOpen=t.id;go("agile_board")},k:"scrum sprint velocity "+t.po}));curStories().forEach(s=>o.push({g:"Stories",t:s.id+" "+s.t,m:s.st+" · "+s.pts+" pts",c:"--w1",f:()=>{go("agile_board");storyDrawer(s.id)},k:tmName(s.tm)}));PIS.forEach(p=>o.push({g:"Increments",t:p.n,m:p.st,c:"--u3",f:()=>{S.v.rel_av=4;go("agile_art")},k:"program increment pi planning"}));return o});
ASKX.push(q=>{const l=q.toLowerCase();
 if(/(release|readiness|go.?no.?go|clash|deployment|dora|lead time|change failure|exit criteria|rollback)/.test(l)&&!/(incident|ticket)/.test(l)){go("itsm_rel");const o=openRels(),b=relOf("REL-2611"),hard=o.filter(r=>clOf(r).some(c=>c.k==="hard")),d=dora();say(q,{t:`<b>${o.length} releases</b> are open. The Standards beta (REL-2611, ${fd(b.date)}) is <b>${readiness(b)}%</b> ready. ${hard.length} have a hard clash (${hard.map(r=>r.id).join(", ")||"none"}). DORA, last 30 days: ${d.df} deployments a week, lead time ${d.lt} hours, ${d.cfr}% failed, ${d.ttr} hours to restore.`,steps:["Read release records","Evaluated exit criteria","Ran clash rules against the calendar"]});return true}
 if(/(sprint|burndown|velocity|backlog|story points|user stor|pull request|kanban|definition of done)/.test(l)){go("agile_board");const cs=curStories(),dn=sum(cs.filter(s=>s.st==="Done"),s=>s.pts),cm=sum(cs,s=>s.pts);say(q,{t:`Sprint <b>${CURSP}</b> is on day ${DAYN} of 10 with <b>${dn} of ${cm} points</b> done. ${PRS.filter(p=>p.st!=="Merged").length} pull requests are open and ${STORY.filter(s=>s.st!=="Done"&&!s.sp).length.toLocaleString("en-US")} stories wait in backlogs. Escaped defect rate is ${escRate()}%.`,steps:["Read the sprint board","Summed committed and done points"]});return true}
 if(/(program increment|pi planning|wsjf|release train|safe|predictab|inspect and adapt|system demo|enabler)/.test(l)){go("agile_art");say(q,{t:`Two release trains execute <b>PI 26.4</b>. Predictability last increment: <b>${predOf("26.3")}%</b> (healthy from 80%). ${lateFeats().length} features are forecast after their release date and ${DEPS.filter(d=>d.st==="At risk").length} dependencies are at risk.`,steps:["Read PI objectives","Checked dependencies and risks"]});return true}
 return false});

/* ---------- other modules can reach us here ---------- */
window.RELX={get releases(){return ALLR()},get trains(){return ARTS},get teams(){return TEAM},gates:id=>{const r=relOf(id);return r?gateRows(r):[]},readiness:id=>{const r=relOf(id);return r?readiness(r):0},clashes:id=>{const r=relOf(id);return r?clOf(r):[]},exitCriteria:id=>{const r=relOf(id);return r?crit(r):[]},recommend:id=>{const r=relOf(id);return r?recommend(r):null},open:id=>{go("itsm_rel");relDrawer(id)},dora:()=>dora(),
 createRelease:(o)=>{o=o||{};const nid="REL-"+(2619+REL.filter(x=>x.id>"REL-2618"&&/^REL-26/.test(x.id)).length);const r=RR(nid,o.n||o.name||"New release",o.ver||"1.0.0",o.ty||"Minor",o.svc||"Standards Platform",o.art==="none"?"":(o.art||"art1"),o.proj||"","Planning",o.start||TODAYI,o.date||o.start||TODAYI,o.rm||"Nia Brooks",{feats:o.feats||[],chg:o.chg||[],team:o.team||[],note:o.note||"",man:"NNNNNNNNNN"});REL.push(r);rebuild();clReset();if(o.gen!==false)genTasks(r);audit("created release",r.id+" · "+r.n);return {ok:true,id:r.id}},
 goNoGo:(id,dec,who,note,risk)=>{const r=relOf(id);if(!r)return {ok:false,error:"Unknown release "+id};const rec=recommend(r);dec=dec||rec[0];if(dec==="Go"&&rec[0]!=="Go"&&!risk)return {ok:false,error:"Recommendation is "+rec[0]+"; name who accepts the risk",recommendation:rec[0]};r.gng.push({dec,by:who||r.rm,at:TODAYI,note:note||rec[2],risk:risk||""});const t=tasksOf(r).find(x=>x.k==="gng");if(t&&dec!=="No-go"){t.st="Done";t.done=TODAYI}if(dec!=="No-go"&&r.st!=="Scheduled")r.st="Scheduled";audit("go or no-go",r.id+" · "+dec);return {ok:true,id:r.id,decision:dec,state:r.st}}};

/* ---------- events ---------- */
const TABV=()=>S.screen==="agile_board"?"rel_bv":S.screen==="agile_art"?"rel_av":"rel_v";
function moveStory(id,to){const s=sOf(id);if(!s||s.st===to)return false;if(to==="Done"){const g=dodGaps(s);if(g.length){toast(s.id+" does not meet the definition of done: "+g[0]+(g.length>1?" (+"+(g.length-1)+" more)":""),"warn");return false}}
 const lim={"In progress":6,"In review":4,"Testing":4};if(lim[to]&&s.sp===CURSP&&curStories([s.tm]).filter(x=>x.st===to).length>=lim[to])toast(to+" is over its work-in-progress limit for "+tmName(s.tm)+". Finish something before starting more.","warn");setState(s,to);audit("moved story",s.id+" → "+to);toast(s.id+" moved to "+to,"good");return true}
function rankIn(list,idx,s){const a=list.filter(x=>x.id!==s.id);const prev=a[idx-1],next=a[idx];s.rk=prev&&next?(prev.rk+next.rk)/2:prev?prev.rk+1:next?next.rk-1:1}
DND.on("rel_kan",(id,fr,to)=>{if(fr!==to)moveStory(id,to.slice(2));render()});
DND.on("rel_plan",(id,fr,to,idx)=>{const s=sOf(id);if(!s)return;const sp=to==="bl"?null:to.slice(3);const was=s.sp;s.sp=sp;const list=STORY.filter(x=>x.tm===s.tm&&x.st!=="Done"&&(x.sp||null)===sp).sort((a,b)=>a.rk-b.rk);rankIn(list,idx,s);STORY.filter(x=>x.tm===s.tm&&x.st!=="Done").sort((a,b)=>a.rk-b.rk).forEach((x,i)=>x.rk=i+1);
 const t=tmOf(s.tm);if(sp){const cm=sum(STORY.filter(x=>x.tm===s.tm&&x.sp===sp),x=>x.pts),cap=capOf(t,"x");if(cm>cap)toast(t.n+" is now at "+cm+" points against a capacity of "+cap,"warn");else toast(s.id+" planned into sprint "+sp+" ("+cm+"/"+cap+" points)","good");if(!s.dor)toast(s.id+" is not ready: refine it before the sprint starts","warn")}else toast(s.id+(was?" returned to the backlog":" re-ranked to position "+(idx+1)),"good");audit("planned story",s.id+" → "+(sp||"backlog"));rebuild();render()});
DND.on("rel_prog",(id,fr,to,idx)=>{const fs=FEAT.filter(f=>f.st!=="Done"&&f.pi!=="26.3").sort((a,b)=>(b.rk!=null?b.rk:wsjf(b)*10)-(a.rk!=null?a.rk:wsjf(a)*10));const f=ftOf(id),a=fs.filter(x=>x.id!==id),key=x=>x.rk!=null?x.rk:wsjf(x)*10,prev=a[idx-1],next=a[idx];f.rk=prev&&next?(key(prev)+key(next))/2:prev?key(prev)-1:key(next)+1;audit("re-ranked program backlog",id+" to #"+(idx+1)+" (manual override of WSJF)");toast(id+" moved to #"+(idx+1)+". The WSJF score is "+wsjf(f)+"; the override is logged.","good");render()});
DND.on("rel_gng",(id,fr,to)=>{if(fr!==to)gngForm(id,to.slice(4));else render()});
DND.on("rel_pi",(id,fr,to)=>{const [ft,tm]=id.split("@"),[,t2,it]=to.split(":");if(t2!==tm){toast("A feature stays with its team. Add the other team to the feature to share it.","warn");render();return}R.pl=R.pl||{};R.pl[id]=it;const c=cellLoad(tm,it),f=ftOf(ft),rl=f.rel?relOf(f.rel):null;toast(ft+" now finishes in "+(it.endsWith(".5")?"the innovation and planning iteration":"iteration "+it.slice(-1))+(c.load>c.cap?". That iteration is over capacity.":"")+(rl&&isOpen(rl)&&spOf(it).from>rl.date?". That is after release "+rl.id+" ("+fd(rl.date)+").":""),c.load>c.cap?"warn":"good");audit("moved feature in PI plan",id+" → "+it);render()});
DND.on("rel_roam",(id,fr,to)=>{const r=RISKS.find(x=>x.id===id);if(r&&fr!==to){r.roam=to.slice(5);audit("ROAM status",id+" → "+r.roam);toast("Risk is now "+r.roam,"good")}render()});

