 if(D("data-rel-runauto")){const s=sOf(t.dataset.relRunauto),r=RNG(s.id+"auto")();s.ta.p=r<.15?Math.max(0,s.ta.n-1):s.ta.n;audit("Test Agent ran suite",s.id+" "+s.ta.p+"/"+s.ta.n);toast(s.ta.p===s.ta.n?"Test Agent: all "+s.ta.n+" automated tests pass":"Test Agent: 1 test failed. Open the pipeline run for the log.",s.ta.p===s.ta.n?"good":"warn");storyDrawer(s.id);render();return}
